"""Static, private-data-free landing page with no third-party resources."""
import html
from datetime import datetime
from src.models import LABELS

def render_site(state: dict, base_url: str) -> str:
    esc = html.escape
    url = base_url.rstrip('/') + '/calendar.ics'
    cards = []
    for category, h in state['health'].items():
        links = ' · '.join(f'<a href="{esc(u)}">Official source {i+1}</a>' for i,u in enumerate(h['source_urls']))
        notes = ''.join(f'<li>{esc(n)}</li>' for n in h['notes'])
        certainty = ' · '.join(f'{v} {k}' for k,v in h['certainty'].items()) or 'No scheduled dates'
        cards.append(f'''<article class="source"><div class="row"><h3>{esc(LABELS[category])}</h3><span class="badge {esc(h['status'])}">{esc(h['status'])}</span></div><p class="count">{h['count']} <small>upcoming events</small></p><p>{esc(certainty)}</p><dl><dt>Schedule through</dt><dd>{esc(h['through'] or 'Not available')}</dd><dt>Last verified</dt><dd>{esc(h['last_success'] or 'No successful verification')}</dd><dt>Last attempt</dt><dd>{esc(h['last_attempt'])}</dd></dl><ul>{notes}</ul><p class="links">{links}</p></article>''')
    events = []
    for r in sorted(state['events'], key=lambda r:r['start'])[:24]:
        start = r['start'] if r['all_day'] else datetime.fromisoformat(r['start']).astimezone(__import__('zoneinfo').ZoneInfo('Europe/London')).strftime('%Y-%m-%d %H:%M %Z')
        events.append(f'<tr><td>{esc(start)}</td><td>{esc(r["title"])}<small>{esc(r["phase"])} · {esc(r["certainty"])}</small></td></tr>')
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Free macroeconomic and equity index events calendar, with official sources and visible schedule health."><title>Macro &amp; Index Events</title><link rel="icon" href="data:,"><style>
:root{color-scheme:light;--ink:#172c35;--muted:#52656c;--line:#d9e3e3;--accent:#006b63}*{box-sizing:border-box}body{margin:0;background:#f5f8f7;color:var(--ink);font:16px/1.6 system-ui,-apple-system,sans-serif}main{max-width:1120px;margin:auto;padding:44px 24px}a{color:var(--accent);text-underline-offset:3px}header{padding:25px 0 32px;max-width:850px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:12px;font-weight:750;color:var(--accent)}h1{font-size:clamp(36px,6vw,64px);letter-spacing:-.045em;line-height:1.1;margin:16px 0 22px}h2{font-size:25px;letter-spacing:-.025em;margin-top:40px}h3{font-size:18px;margin:0}p{margin:12px 0}.intro{font-size:20px;color:var(--muted)}.subscribe,.source,.upcoming{background:white;border:1px solid var(--line);border-radius:15px;padding:24px}.subscribe{border-top:4px solid var(--accent)}.urlrow{display:flex;gap:10px}input{width:100%;min-width:0;font:14px ui-monospace,monospace;padding:14px;border:1px solid #acbfbd;border-radius:7px;background:#f6faf9;color:var(--ink)}button{background:var(--accent);color:white;border:0;border-radius:7px;padding:12px 22px;font:inherit;cursor:pointer}.note,small,dt{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.row{display:flex;justify-content:space-between;align-items:center;gap:8px}.badge{font-size:12px;border-radius:30px;padding:3px 9px;background:#e1f3e9;color:#175735}.partial{background:#fff0cc;color:#795300}.unavailable{background:#fde5e5;color:#922d2d}.count{font-size:29px;font-weight:700;margin-bottom:0}dl{display:grid;grid-template-columns:125px 1fr;gap:5px 8px;font-size:12px}dd{margin:0;overflow-wrap:anywhere}ul,ol{padding-left:22px}.source li{font-size:13px;margin-bottom:8px}.links{font-size:13px}.upcoming{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:12px 8px;vertical-align:top}td:first-child{white-space:nowrap}td small{display:block}footer{border-top:1px solid var(--line);margin-top:40px;padding-top:24px;font-size:13px;color:var(--muted)}code{overflow-wrap:anywhere}@media(max-width:700px){main{padding:24px 16px}.grid{grid-template-columns:1fr}.source,.subscribe,.upcoming{padding:18px}.urlrow{flex-direction:column}dl{grid-template-columns:105px 1fr}}
</style></head><body><main><header><div class="eyebrow">Public calendar · Free · No adverts</div><h1>Macro &amp; Index Events</h1><p class="intro">Macro releases, index dates and US federal elections in one calendar. Subscribe once, with official sources and a clear view of what is confirmed.</p></header><section class="subscribe"><h2 style="margin-top:0">Add it to your calendar</h2><label for="ics">ICS subscription URL</label><div class="urlrow"><input id="ics" readonly value="''' + esc(url) + '''"><button type="button" id="copy">Copy URL</button></div><p id="copy-status" aria-live="polite" class="note"></p><ol><li>Open Google Calendar in a desktop browser.</li><li>Choose <strong>Other calendars → + → From URL</strong> (or Settings → Add calendar → From URL).</li><li>Paste the URL above and choose <strong>Add calendar</strong>.</li></ol><p><a href="calendar.ics">Open ICS feed</a> · <a href="https://support.google.com/calendar/answer/37100">Google subscription help</a></p><p class="note">Subscribe by URL to receive updates; importing a downloaded file is a one-time copy. The feed refreshes daily. Google controls its own refresh interval, so changes may take time to appear.</p><p class="note">Each event includes a 24-hour reminder, but Google may ignore reminders in subscribed feeds. Under Settings, select this calendar and add a 1-day event notification if that option is available. Read-only subscribed calendars may not offer notification controls.</p></section><h2>Coverage &amp; source health</h2><p>Last successful calendar build: <strong>''' + esc(state['generated_at']) + '''</strong><br><span class="note">Macro/index horizon: ''' + esc(state['horizon']) + '''. US elections use a separate four-year lookahead. Each source may publish a shorter schedule. “Last verified” is distinct from the latest refresh attempt.</span></p><p class="note">Confirmed = official scheduled date. Provisional = explicitly tentative. Calculated = derived from a published rule, not an individually confirmed announcement. Partial = fallback, retained dates, or incomplete source coverage; read each limitation below. All-day entries deliberately avoid invented publication times.</p><div class="grid">''' + ''.join(cards) + '''</div><h2>Next events</h2><p class="note">Timed events shown in Europe/London. All-day index and election entries retain the source calendar date.</p><div class="upcoming"><table><thead><tr><th>Date / London time</th><th>Event</th></tr></thead><tbody>''' + ''.join(events) + '''</tbody></table></div><footer><p>No tracking, cookies, adverts, API keys or paid data feeds.</p><p><a href="https://github.com/ChetinSelim/macro-index-calendar">Source code &amp; limitations</a> · <a href="health.json">Machine-readable health</a> · <a href="changes.json">Schedule changes</a> · <a href="https://github.com/ChetinSelim/macro-index-calendar/actions">Automation status</a></p><p>Schedules can change. Check the linked official source before relying on an event.</p></footer></main><script>document.getElementById('copy').addEventListener('click',async()=>{const input=document.getElementById('ics');try{await navigator.clipboard.writeText(input.value);document.getElementById('copy-status').textContent='Subscription URL copied.'}catch(e){input.select();document.getElementById('copy-status').textContent='Select and copy the URL above.'}});</script></body></html>'''
